                var entry = jar.getEntry("STAMP");
                if (entry == null) {
                    return false;
                }
                String got = new String(jar.getInputStream(entry).readAllBytes(),
                        StandardCharsets.UTF_8).trim();
                return want.equals(got);
            }
        } catch (Exception ex) {
            return false;
        }
    }

    private static String json(String value) {
        return value.replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\n", "\\n")
                .replace("\r", "\\r")
                .replace("\t", "\\t");
    }
}
